#!/usr/bin/env node
'use strict';

/**
 * Live TVS acceptance. Requires a running local-only JARVIS Windows dev stack
 * (npm run dev:windows), a real Ollama service, and an isolated Windows runner.
 * It does not use fixture decisions or mock model responses.
 *
 * This script executes dependencies/build output generated by the agent. Run
 * only on a disposable Windows VM/runner with no secrets or production access.
 */
const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');
const crypto = require('node:crypto');
const { spawnSync, spawn } = require('node:child_process');

const root = path.resolve(__dirname, '../..');
const promptPath = path.join(root, 'benchmarks/autonomy/fixtures/tvs-motor-original-3954.txt');
const workspace = path.resolve(process.env.JARVIS_AGENT_WORKSPACE || '');
const model = process.env.JARVIS_OLLAMA_MODEL || 'qwen2.5-coder:3b';
const base = process.env.JARVIS_OLLAMA_BASE_URL || 'http://127.0.0.1:11434';
const app = process.env.JARVIS_BASE_URL || 'http://127.0.0.1:3000';
const evidencePath = path.resolve(process.env.JARVIS_LIVE_EVIDENCE || 'artifacts/tvs-live-acceptance.json');
const evidence = {
  startedAt: new Date().toISOString(), model, ollamaBase: base, app,
  prompt: {}, inference: {}, task: { events: [], toolCalls: 0 }, artifact: {}, build: {}, preview: {},
  verdict: 'NOT_ACCEPTED', errors: []
};
const sha = b => crypto.createHash('sha256').update(b).digest('hex');

function assert(cond, message) { if (!cond) throw new Error(message); }
async function save() {
  await fsp.mkdir(path.dirname(evidencePath), { recursive: true });
  evidence.finishedAt = new Date().toISOString();
  await fsp.writeFile(evidencePath, JSON.stringify(evidence, null, 2) + '\n');
}
async function getJson(url, options = {}) {
  const res = await fetch(url, options);
  const text = await res.text();
  if (!res.ok) throw new Error(`HTTP ${res.status} ${url}: ${text.slice(0, 500)}`);
  return text ? JSON.parse(text) : {};
}
function isolatedBuildEnv(cwd) {
  const env = {};
  for (const key of ['PATH','SystemRoot','WINDIR','TEMP','TMP','USERPROFILE','APPDATA','LOCALAPPDATA']) {
    if (process.env[key]) env[key] = process.env[key];
  }
  env.HOME = cwd;
  env.CI = '1';
  env.NODE_ENV = 'production';
  env.GIT_TERMINAL_PROMPT = '0';
  env.GIT_CONFIG_NOSYSTEM = '1';
  env.npm_config_cache = path.join(cwd,'.npm-cache');
  env.npm_config_audit = 'false';
  env.npm_config_fund = 'false';
  return env;
}
function run(command, args, cwd, timeout = 20 * 60_000) {
  const npmShim = /^(?:npm|npm\.cmd)$/i.test(command);
  const r = spawnSync(command, args, {
    cwd, encoding: 'utf8', timeout, windowsHide: true,
    // Only the fixed npm shim uses cmd.exe; Node/Vite binaries run with shell:false.
    shell: npmShim, env: isolatedBuildEnv(cwd), maxBuffer: 16 * 1024 * 1024
  });
  if (r.error) throw r.error;
  if (r.status !== 0) throw new Error(`${command} ${args.join(' ')} failed (${r.status})\\n${(r.stdout||'').slice(-4000)}\\n${(r.stderr||'').slice(-4000)}`);
  return { stdout: r.stdout, stderr: r.stderr };
}
async function findProject(dir, depth = 0) {
  if (depth > 4) return null;
  let entries;
  try { entries = await fsp.readdir(dir, { withFileTypes: true }); } catch { return null; }
  if (entries.some(e => e.isFile() && e.name === 'package.json') &&
      entries.some(e => e.isFile() && e.name === 'index.html')) return dir;
  for (const e of entries) {
    if (!e.isDirectory() || ['node_modules','.git','.next','dist','build'].includes(e.name)) continue;
    const found = await findProject(path.join(dir,e.name),depth+1);
    if (found) return found;
  }
  return null;
}

(async()=>{
  try {
    assert(process.platform === 'win32', 'This acceptance must run on native Windows.');
    assert(workspace && path.isAbsolute(workspace), 'Set JARVIS_AGENT_WORKSPACE to an absolute disposable workspace path.');
    await fsp.mkdir(workspace,{recursive:true});
    const prompt = (await fsp.readFile(promptPath,'utf8')).replace(/\r\n/g,'\n');
    evidence.prompt = { source:'https://prompts.chat/prompts/cmuz5u62d0004l904ys2nmj7u_premium-tvs-motor-digital-showroom-website', characters:[...prompt].length, sha256:sha(prompt) };
    assert([...prompt].length === 3954, `Pinned TVS prompt character count mismatch: ${[...prompt].length}`);

    // Confirm Ollama is real and the requested model is installed.
    const tags = await getJson(new URL('/api/tags',base));
    const installed = (tags.models||[]).some(x => x.name === model || x.name.startsWith(model+':'));
    assert(installed, `Ollama model not installed: ${model}`);

    // Real, non-fixture inference probe through Ollama's HTTP API.
    const t0 = Date.now();
    const warm = await getJson(new URL('/api/chat',base),{
      method:'POST',headers:{'content-type':'application/json'},
      body:JSON.stringify({model,messages:[{role:'user',content:'Return one short JSON object with keys "ready" and "engine"; ready must be true and engine must be "ollama".'}],format:'json',stream:false,keep_alive:'5m'}),
      signal:AbortSignal.timeout(120_000)
    });
    const answer = warm.message?.content;
    assert(typeof answer==='string' && answer.length>0,'Ollama returned no actual model response.');
    evidence.inference = { durationMs:Date.now()-t0, responseChars:answer.length, responseSha256:sha(answer), done:warm.done===true, evalCount:warm.eval_count??null, promptEvalCount:warm.prompt_eval_count??null };

    // Bootstrap the dedicated loopback-only owner session and retain its cookie.
    // A successful GET alone is not authentication for the subsequent task POST.
    const sessionResponse = await fetch(new URL('/api/jarvis/auth/session',app));
    const sessionText = await sessionResponse.text();
    assert(sessionResponse.ok, `JARVIS session endpoint returned HTTP ${sessionResponse.status}: ${sessionText.slice(0,500)}`);
    const sessionData = JSON.parse(sessionText);
    assert(sessionData.authenticated === true, 'Local development session was not authenticated: ' + JSON.stringify(sessionData));
    const setCookies = typeof sessionResponse.headers.getSetCookie === 'function'
      ? sessionResponse.headers.getSetCookie()
      : [sessionResponse.headers.get('set-cookie')].filter(Boolean);
    const sessionCookie = setCookies.map(value => value.split(';',1)[0]).filter(Boolean).join('; ');
    assert(sessionCookie.length > 0, 'Local session endpoint did not issue a session cookie.');

    const controller = new AbortController();
    const kill = setTimeout(()=>controller.abort(new Error('JARVIS task exceeded 60-minute acceptance budget')),60*60_000);
    let response;
    try {
      response = await fetch(new URL('/api/jarvis/task',app),{
        method:'POST',headers:{'content-type':'application/json','accept':'text/event-stream','cookie':sessionCookie},
        body:JSON.stringify({objective:prompt,stepBudget:24}),
        signal:controller.signal
      });
      assert(response.ok, `JARVIS task API returned HTTP ${response.status}: ${(await response.text()).slice(0,1000)}`);
      const reader=response.body.getReader();
      const decoder=new TextDecoder();
      let buffer='',eventName='message';
      const ingest=raw=>{
        const block=raw.trim(); if(!block)return;
        let data='';
        for(const line of block.split(/\r?\n/)){
          if(line.startsWith('event:'))eventName=line.slice(6).trim();
          else if(line.startsWith('data:'))data+=line.slice(5).trim();
        }
        if(!data)return;
        let payload;try{payload=JSON.parse(data)}catch{payload={raw:data};}
        evidence.task.events.push({event:eventName,payload});
        if(eventName==='step' && payload.step?.kind==='tool_call')evidence.task.toolCalls++;
        if(eventName==='final')evidence.task.final=payload;
        if(eventName==='error')evidence.task.errors=(evidence.task.errors||[]).concat(payload);
        eventName='message';
      };
      for(;;){
        const {done,value}=await reader.read();
        if(done)break;
        buffer+=decoder.decode(value,{stream:true});
        let ix;
        while((ix=buffer.indexOf('\n\n'))>=0){ingest(buffer.slice(0,ix));buffer=buffer.slice(ix+2);}
      }
      buffer+=decoder.decode();if(buffer.trim())ingest(buffer);
    } finally { clearTimeout(kill); }
    assert(evidence.task.final, 'JARVIS stream ended without a final task event.');
    assert(evidence.task.final.status==='completed', `JARVIS did not complete task: ${evidence.task.final.status}`);
    assert(evidence.task.toolCalls>0, 'JARVIS claimed completion without any autonomous tool-call events.');

    // Independently inspect the actual workspace; do not trust the model's final text.
    const project=await findProject(workspace);
    assert(project, 'No project root with both package.json and index.html was found in the authorized workspace.');
    const pkg=JSON.parse(await fsp.readFile(path.join(project,'package.json'),'utf8'));
    for(const dep of ['react','react-dom','vite']) assert(pkg.dependencies?.[dep]||pkg.devDependencies?.[dep],`Generated project missing required dependency: ${dep}`);
    const sourceFiles=[];
    async function walk(dir,depth=0){
      if(depth>6)return;
      for(const e of await fsp.readdir(dir,{withFileTypes:true})){
        if(e.isDirectory()&&['node_modules','.git','dist'].includes(e.name))continue;
        const p=path.join(dir,e.name);
        if(e.isDirectory())await walk(p,depth+1);
        else if(/\.(tsx?|jsx?|css|html)$/.test(e.name))sourceFiles.push(p);
      }
    }
    await walk(project);
    assert(sourceFiles.length>=4,'Generated site has too few source files to qualify as a complete website.');
    const allText=(await Promise.all(sourceFiles.map(p=>fsp.readFile(p,'utf8').catch(()=>'')))).join('\n');
    for(const token of ['TVS','THE NEXT RIDE IS HERE','BOOK TEST RIDE','COMPARE']) {
      assert(allText.toLowerCase().includes(token.toLowerCase()),`Generated website missing required content marker: ${token}`);
    }
    assert(!/lorem ipsum|TODO: implement|placeholder text/i.test(allText),'Generated website contains placeholder/TODO content.');
    evidence.artifact={project:path.relative(workspace,project),sourceFiles:sourceFiles.length,packageName:pkg.name,dependencies:Object.keys({...pkg.dependencies,...pkg.devDependencies}),sourceSha256:sha(allText)};

    // Build in the disposable runner. Ignore arbitrary install lifecycle scripts;
    // rebuild only esbuild, then invoke the known Vite CLI directly (not package scripts).
    if(fs.existsSync(path.join(project,'package-lock.json'))) run('npm.cmd',['ci','--ignore-scripts','--no-audit','--no-fund'],project);
    else run('npm.cmd',['install','--ignore-scripts','--no-audit','--no-fund'],project);
    if(fs.existsSync(path.join(project,'node_modules/esbuild'))) run('npm.cmd',['rebuild','esbuild'],project);
    const viteCli=path.join(project,'node_modules','vite','bin','vite.js');
    assert(fs.existsSync(viteCli),'Vite CLI missing after dependency installation.');
    run(process.execPath,[viteCli,'build'],project);
    assert(fs.existsSync(path.join(project,'dist','index.html')),'Vite build did not produce dist/index.html.');
    evidence.build={status:'PASS',distIndexHtmlBytes:(await fsp.stat(path.join(project,'dist','index.html'))).size};

    const preview=spawn(process.execPath,[viteCli,'preview','--host','127.0.0.1','--port','4173','--strictPort'],{cwd:project,stdio:'ignore',windowsHide:true,env:isolatedBuildEnv(project)});
    try {
      let ok=false,lastError='';
      for(let i=0;i<60;i++){
        try{const r=await fetch('http://127.0.0.1:4173');if(r.ok){const html=await r.text();assert(html.includes('<div')||html.includes('<main')||html.includes('<body'),'Preview returned unexpected HTML.');ok=true;evidence.preview={status:'PASS',httpStatus:r.status,htmlBytes:html.length};break;}}
        catch(e){lastError=e.message;}
        await new Promise(r=>setTimeout(r,1000));
      }
      assert(ok,'Built website preview failed to return HTTP 200: '+lastError);
    } finally { preview.kill(); }

    evidence.verdict='PASS';
    console.log('LIVE TVS AUTONOMY ACCEPTANCE PASS');
  } catch(err) {
    evidence.errors.push(String(err?.stack||err));
    console.error('LIVE TVS AUTONOMY ACCEPTANCE FAILED:',err?.message||err);
    process.exitCode=1;
  } finally { await save(); }
})();
